window.VO = [{"id":"n02","text":"Watch the money.","at":0.2,"t0":0.1,"t1":1.095},{"id":"n01","text":"He's about to con the chaiwala.","at":2.51,"t0":1.255,"t1":2.92},{"id":"u01","text":"Five hundred? For a ten-rupee chai?","at":6.34,"t0":3.17,"t1":5.755},{"id":"u02","text":"Two hundred.","at":13.11,"t0":6.555,"t1":7.65},{"id":"u03","text":"Four hundred.","at":15.3,"t0":7.65,"t1":8.85},{"id":"u04","text":"Four-fifty.","at":17.7,"t0":8.85,"t1":9.975},{"id":"u05","text":"Four-sev—","at":19.95,"t0":9.975,"t1":10.93},{"id":"u06","text":"Oh, you have change? Then take your five hundred back.","at":22.7,"t0":11.35,"t1":14.68},{"id":"u07","text":"Arre, sorry, sorry!","at":32.76,"t0":16.38,"t1":18.41},{"id":"u08","text":"Four-seventy.","at":36.92,"t0":18.46,"t1":19.69},{"id":"u09","text":"Four-ninety.","at":39.38,"t0":19.69,"t1":20.735},{"id":"u10","text":"Come again!","at":43.57,"t0":21.785,"t1":22.72},{"id":"n03","text":"So.","at":46.04,"t0":23.02,"t1":23.595},{"id":"n04","text":"How much did he steal?","at":47.75,"t0":23.875,"t1":25.24},{"id":"n05","text":"Nothing was hidden.","at":52.88,"t0":26.44,"t1":27.565},{"id":"n06","text":"His five hundred came down, and the uncle counted out four-fifty.","at":55.93,"t0":27.965,"t1":31.74},{"id":"n07","text":"Then a ten for the chai, and his five hundred went back.","at":64.38,"t0":32.19,"t1":35.16},{"id":"n08","text":"But one raised eyebrow, and the uncle counted on: four-seventy, four-ninety.","at":72.22,"t0":36.11,"t1":40.27},{"id":"n09","text":"Four hundred and ninety.","at":81.94,"t0":40.97,"t1":42.42},{"id":"n10","text":"He never picked a pocket.","at":86.34,"t0":43.17,"t1":44.705},{"id":"n11","text":"The uncle counted it all out for him.","at":89.91,"t0":44.955,"t1":46.94},{"id":"n12","text":"Your brain can only hold about four things at once, so he kept handing the uncle one more.","at":95.08,"t0":47.54,"t1":52.385},{"id":"n13","text":"That's why police tell shopkeepers: one deal at a time.","at":105.87,"t0":52.935,"t1":56.085},{"id":"c01","text":"Five hundred? For a ten-rupee chai?","at":114.17,"t0":57.085,"t1":59.485}];
